<script>
  import { onMount } from 'svelte';
  import { carregar, brl, lerEstado, gravarEstado, criarPerfil, escolherPessoaMigrada, pessoaLocal, parceiro, desvincular, registrarEvento, registrarMetrica, ultimaAvaliacao, QUALIDADE_PADRAO } from '$lib/dados.js';
  import { TIPOS, TIPO_LABEL, CONTINENTES, CONT_LABEL, DURACOES, flag, pais } from '$lib/filtros.js';
  import { criarPacote, importarPacote, linkComPacote, pacoteDoHash } from '$lib/troca.js';
  import { passaQualidade, pontuarDupla } from '$lib/ranking.js';
  import { motivoInelegivel, passaFiltros, agruparOfertas, ordenar, curarHome, explicar, oportunidade } from '$lib/selecao.js';

  let local = $state(lerEstado()); let dados = $state(null); let erro = $state(''); let aba = $state('inicio');
  let nome = $state(''); let cidade = $state('São Paulo'); let perfil = $state(false); let preferencias = $state(false); let ajustes = $state(false); let filtrosAbertos = $state(false);
  let feedback = $state(null); let motivos = $state([]); let nota = $state(''); let aviso = $state(''); let filtroQualidade = $state(true); let nomeBusca = $state('');
  let filtros = $state({ escopo:'perfil', tipos:[], continente:'', pais:'', orcamentoCasal:8000, duracao:'perfil', direto:false, escalas:'', semVisto:false, deal:false, afinidade:'', mes:'', origem:'SAO', classe:'', bagagem:false });
  let filtrosEscapada = $state({ formato:'', deslocamento:'', tipo:'', estrelas:'', avaliacao:'' });
  const eu = $derived(pessoaLocal(local)); const outra = $derived(parceiro(local)); const pessoas = $derived(Object.values(local.pessoas ?? {}));
  const naoVistos = $derived(local.eventos.filter((e) => e.pessoaId !== local.aparelho.pessoaId && !local.eventosVistos.includes(e.id)));
  const pendentes = $derived(local.eventos.filter((e) => e.pessoaId === local.aparelho.pessoaId && (!local.ultimoCompartilhamento || e.criadoEm > local.ultimoCompartilhamento)));
  const perfilServidor = $derived(dados?.perfis?.[0] ?? { id:'ale-andreia', noites:{min:7,max:14} });
  const duracao = $derived(DURACOES.find(([id])=>id===filtros.duracao)?.slice(2) ?? [perfilServidor.noites?.min ?? 0, perfilServidor.noites?.max ?? 30]);
  const ofertasPontuadas = $derived((dados?.ofertas ?? []).map((o) => ({ ...o, itemTipo:'viagem', ranking:pontuarDupla(o,pessoas,local.gosto,local.eventos) })));
  const ofertas = $derived.by(() => ordenar(agruparOfertas(ofertasPontuadas.filter((o) => !local.descartados.includes(o.id) && !motivoInelegivel(o,{ perfilId:perfilServidor.id, escopo:filtros.escopo, precoMax:+filtros.orcamentoCasal/2, noitesMin:duracao[0], noitesMax:duracao[1] }) && passaFiltros(o,filtros))).map((o)=>({ ...o, explicacao:explicar(o) }))));
  const destaques = $derived(curarHome(ofertas,4).map((o)=>({ ...o, explicacao:explicar(o) })));
  const paisesDisponiveis = $derived([...new Map(ofertasPontuadas.filter((o)=>o.pais_iso2).map((o)=>[o.pais_iso2,pais(o.pais_iso2,o.pais_texto)])).entries()].sort((a,b)=>a[1].localeCompare(b[1])));
  const mesesDisponiveis = $derived([...new Set(ofertasPontuadas.map((o)=>(o.janela_inicio||o.descoberto_em||'').slice(0,7)).filter(Boolean))].sort());
  const escapadas = $derived((dados?.escapadas ?? []).map((e)=>({ ...e,itemTipo:'escapada',ranking:pontuarDupla(e,pessoas,local.gosto,local.eventos) })).filter((e)=>(!filtroQualidade||pessoas.every((p)=>passaQualidade(e,p.qualidade??QUALIDADE_PADRAO)))&&(!filtrosEscapada.estrelas||e.estrelas>=+filtrosEscapada.estrelas)&&(!filtrosEscapada.avaliacao||e.avaliacao>=+filtrosEscapada.avaliacao)&&(!filtrosEscapada.formato||e.tipo===filtrosEscapada.formato)&&(!filtrosEscapada.tipo||(e.tags??e.tipos??[]).includes(filtrosEscapada.tipo))).sort((a,b)=>b.ranking.pontos-a.ranking.pontos));
  const filtrosAtivos = $derived([filtros.escopo!=='perfil',filtros.tipos.length,filtros.continente,filtros.pais,+filtros.orcamentoCasal!==8000,filtros.duracao!=='perfil',filtros.direto,filtros.escalas!=='',filtros.semVisto,filtros.deal,filtros.afinidade,filtros.mes,filtros.classe,filtros.bagagem].filter(Boolean).length);
  const chipsAtivos = $derived([
    filtros.escopo==='domestico'&&['Brasil',()=>filtros.escopo='perfil'], filtros.escopo==='internacional'&&['Exterior',()=>filtros.escopo='perfil'],
    filtros.direto&&['Voo direto',()=>filtros.direto=false], filtros.deal&&['Bom preço',()=>filtros.deal=false], filtros.afinidade==='dupla'&&['Combina com os dois',()=>filtros.afinidade=''],
    filtros.mes&&[`Mês: ${filtros.mes}`,()=>filtros.mes=''], filtros.duracao!=='perfil'&&[DURACOES.find(([id])=>id===filtros.duracao)?.[1],()=>filtros.duracao='perfil'],
    ...filtros.tipos.map((id)=>[TIPO_LABEL[id],()=>filtros.tipos=filtros.tipos.filter((x)=>x!==id)]),
    +filtros.orcamentoCasal!==8000&&[`Até ${brl(filtros.orcamentoCasal)} o casal`,()=>filtros.orcamentoCasal=8000]
  ].filter(Boolean));

  function salvar(e){local=e;gravarEstado(local)}
  onMount(async()=>{local=lerEstado();perfil=!local.aparelho.pessoaId&&!local.migracao?.precisaEscolherPessoa;try{const pacote=pacoteDoHash(location.hash);if(pacote){const r=importarPacote(local,pacote);salvar(r.estado);aviso=r.novos.length?`${pacote.remetente.nome} enviou ${r.novos.length} novidade${r.novos.length>1?'s':''}.`:`Vínculo com ${pacote.remetente.nome} atualizado.`;history.replaceState(null,'',location.pathname+location.search)}}catch(e){aviso=e.message}try{dados=await carregar()}catch(e){erro=e.message}});
  function concluirPerfil(){if(!nome.trim()||!cidade)return;salvar(criarPerfil(local,{nome,cidade}));perfil=false;preferencias=true}
  function toggleGosto(tipo){const id=local.aparelho.pessoaId,atual=local.gosto[id]??[];salvar({...local,gosto:{...local.gosto,[id]:atual.includes(tipo)?atual.filter((x)=>x!==tipo):[...atual,tipo]}})}
  function atualizarQualidade(campo,valor){const p={...eu,qualidade:{...QUALIDADE_PADRAO,...eu.qualidade,[campo]:valor},atualizadoEm:new Date().toISOString()};salvar({...local,pessoas:{...local.pessoas,[p.id]:p}})}
  function avaliar(item,acao){feedback={item,acao};motivos=[];nota=''}
  function concluirFeedback(){const{item,acao}=feedback;let e=registrarEvento(local,{itemId:item.id,itemTipo:item.itemTipo,acao,motivos,nota});if(acao==='salvei')e=item.itemTipo==='escapada'?{...e,escapadasFavoritas:[...new Set([...e.escapadasFavoritas,item.id])]}:{...e,favoritos:[...new Set([...e.favoritos,item.id])]};if(acao==='descartei')e={...e,descartados:[...new Set([...e.descartados,item.id,...(item.alternativas??[]).map((x)=>x.id)])]};salvar(e);feedback=null}
  async function compartilhar(tipo=local.dupla.status==='pareada'?'atualizacao':'convite'){try{const pacote=criarPacote(local,tipo),url=linkComPacote(location.href,pacote),text=tipo==='convite'?`${eu.nome} convidou você para o Viagem para Dois.`:`${eu.nome} marcou novidades no Viagem para Dois.`;if(navigator.share)await navigator.share({title:'Viagem para Dois',text,url});else window.open(`https://wa.me/?text=${encodeURIComponent(`${text}\n${url}`)}`,'_blank','noopener');salvar({...local,dupla:{...local.dupla,id:pacote.duplaId,status:local.dupla.status==='pareada'?'pareada':'convidou'},ultimoCompartilhamento:new Date().toISOString()})}catch(e){if(e.name!=='AbortError')aviso=e.message}}
  function marcarVistos(){salvar({...local,eventosVistos:[...new Set([...local.eventosVistos,...naoVistos.map((e)=>e.id)])]})}
  function confirmarDesvinculo(){if(confirm(`Desvincular de ${outra?.nome??'esta pessoa'}? Seu perfil e suas escolhas serão preservados.`)){salvar(desvincular(local));ajustes=false;aviso='Dupla desvinculada. Você já pode convidar outra pessoa.'}}
  function filtrosPadrao(){return {escopo:'perfil',tipos:[],continente:'',pais:'',orcamentoCasal:8000,duracao:'perfil',direto:false,escalas:'',semVisto:false,deal:false,afinidade:'',mes:'',origem:'SAO',classe:'',bagagem:false}}
  function limparFiltros(){filtros=filtrosPadrao()}
  function toggleTipo(id){filtros.tipos=filtros.tipos.includes(id)?filtros.tipos.filter((x)=>x!==id):[...filtros.tipos,id]}
  function alternarRapido(campo, valor=true){filtros[campo]=filtros[campo]===valor?(campo==='escopo'?'perfil':campo==='afinidade'?'':false):valor;salvar(registrarMetrica(local,'filtro_rapido',{campo,valor:filtros[campo]}))}
  function aplicarFiltros(){salvar(registrarMetrica(local,'filtros_aplicados',{quantidade:filtrosAtivos,resultados:ofertas.length}));filtrosAbertos=false}
  function salvarBusca(){const nomeFinal=nomeBusca.trim()||`Busca ${local.buscasSalvas.length+1}`;salvar({...local,buscasSalvas:[...(local.buscasSalvas??[]),{id:Date.now().toString(36),nome:nomeFinal,filtros:JSON.parse(JSON.stringify(filtros))}]});nomeBusca='';aviso=`“${nomeFinal}” foi salva.`}
  function aplicarBusca(busca){filtros={...filtrosPadrao(),...JSON.parse(JSON.stringify(busca.filtros)),tipos:[...(busca.filtros.tipos??[])]};salvar(registrarMetrica(local,'busca_salva_usada',{id:busca.id}));filtrosAbertos=false}
  function minhaAvaliacao(item){return ultimaAvaliacao(local,item.id)}
  const razoes=(tipo)=>tipo==='escapada'?['localização','avaliação','estrelas','preço','estilo','comodidades']:['destino','preço','datas','classe do voo','escalas','estilo'];
</script>

<svelte:head><title>Viagem para Dois — achados para escapar juntos</title><meta name="apple-mobile-web-app-title" content="Viagem²"/><meta name="application-name" content="Viagem²"/><meta name="description" content="Achados de viagens e escapadas escolhidos para vocês dois."/></svelte:head>
<header class="topbar"><button class="brand" onclick={()=>aba='inicio'}><span>◎</span><b>Viagem²<small>Achados para escapar juntos.</small></b></button>{#if eu}<button class="identity" onclick={()=>ajustes=true}><i>{eu.nome[0]}</i><span>{outra?`${eu.nome} + ${outra.nome}`:eu.nome}<small>{local.dupla.cidade} · ajustar</small></span>{#if naoVistos.length}<em>{naoVistos.length}</em>{/if}</button>{/if}</header>
{#if aviso}<div class="notice"><span>{aviso}</span><button onclick={()=>aviso=''}>×</button></div>{/if}
{#if naoVistos.length}<section class="activity"><b>💛 {outra?.nome??'Sua dupla'} marcou {naoVistos.length} novidade{naoVistos.length>1?'s':''}</b><p>Veja as escolhas recebidas e procurem os matches.</p><button onclick={marcarVistos}>Marcar como vistas</button></section>{/if}
{#if eu}<nav>{#each [['inicio','Para vocês'],['escapadas','Escapadas'],['viagens','Viagens'],['salvos','Salvos']] as [id,label]}<button class:on={aba===id} onclick={()=>aba=id}>{label}{id==='salvos'&&(local.favoritos.length+local.escapadasFavoritas.length)?` ${local.favoritos.length+local.escapadasFavoritas.length}`:''}</button>{/each}</nav>{/if}

{#if erro}<main class="empty"><b>Não foi possível atualizar os achados.</b><p>{erro}</p></main>{:else if !dados}<main class="empty">Carregando os achados…</main>{:else if eu}<main>
{#if aba==='inicio'}
  <section class="hero"><p>OLÁ, {eu.nome.toUpperCase()}</p><h1>O próximo <em>sim</em><br/>começa aqui.</h1><span>{outra?`Uma curadoria diversa para ${eu.nome} e ${outra.nome}, sem repetir o mesmo destino.`:'Configure seus gostos e convide a outra pessoa pelo WhatsApp.'}</span><div class="heroactions"><button onclick={()=>preferencias=true}>Minhas preferências</button><button onclick={()=>filtrosAbertos=true}>Filtros{filtrosAtivos?` (${filtrosAtivos})`:''}</button><button class="primary" onclick={()=>compartilhar()}>{outra?`Enviar novidades${pendentes.length?` (${pendentes.length})`:''}`:'Convidar pelo WhatsApp'}</button></div></section>
  <section class="quickfilters" aria-label="Filtros rápidos"><button class:active={filtros.escopo==='internacional'} onclick={()=>alternarRapido('escopo','internacional')}>🌎 Exterior</button><button class:active={filtros.escopo==='domestico'} onclick={()=>alternarRapido('escopo','domestico')}>🇧🇷 Brasil</button><button class:active={filtros.direto} onclick={()=>alternarRapido('direto')}>✈️ Direto</button><button class:active={filtros.deal} onclick={()=>alternarRapido('deal')}>📉 Bom preço</button><button class:active={filtros.afinidade==='dupla'} onclick={()=>alternarRapido('afinidade','dupla')}>💛 Combina com os dois</button></section>
  {#if chipsAtivos.length}<section class="applied"><span>Filtros:</span>{#each chipsAtivos as [label,remover]}<button onclick={remover}>{label} ×</button>{/each}<button class="clear" onclick={limparFiltros}>Limpar</button></section>{/if}
  <div class="radarline"><b>{[...new Set(ofertas.map((o)=>o.destino_texto))].length} destinos</b><span>· {ofertas.length} oportunidades depois da curadoria do Caçador</span></div>
  {#if !destaques.length}<div class="empty"><b>Nada passou pelos filtros atuais.</b><button onclick={limparFiltros}>Limpar filtros</button></div>{/if}
  <div class="grid">{#each destaques as o}{@const avaliacao=minhaAvaliacao(o)}<article class="card featured"><p class="role">{o.papel}</p><header><span>{flag(o.pais_iso2)}</span><div><h3>{o.destino_texto}</h3><small>São Paulo → {o.destino_texto} · {o.mes}</small></div></header><div class="signals"><span>{o.ranking.pontos}% afinidade</span>{#if oportunidade(o).pontos>=20}<span>📊 oportunidade</span>{/if}{#if o.escalas===0}<span>voo direto</span>{/if}</div><p class="why"><b>Por que apareceu</b>{o.explicacao}</p>{#if avaliacao}<div class:liked={avaliacao.acao==='gostei'} class:disliked={avaliacao.acao==='nao_gostei'} class="myfeedback"><b>{avaliacao.acao==='gostei'?'👍 Você gostou':'👎 Você não gostou'}</b>{#if avaliacao.motivos?.length}<span>{avaliacao.motivos.join(' · ')}</span>{/if}{#if avaliacao.nota}<small>“{avaliacao.nota}”</small>{/if}</div>{/if}<div class="price"><b>{brl(o.preco_brl*(o.por_pessoa?2:1))}<small> para dois</small></b>{#if o.quantidade>1}<span>+{o.quantidade-1} alternativa{o.quantidade>2?'s':''}</span>{/if}</div><div class="actions"><button class:selected={avaliacao?.acao==='nao_gostei'} aria-label={avaliacao?.acao==='nao_gostei'?'Não gostei — marcado':'Não gostei'} onclick={()=>avaliar(o,'nao_gostei')}>👎</button><button class:selected={avaliacao?.acao==='gostei'} aria-label={avaliacao?.acao==='gostei'?'Gostei — marcado':'Gostei'} onclick={()=>avaliar(o,'gostei')}>👍</button><button onclick={()=>avaliar(o,'salvei')}>Salvar</button><a href={o.fontes[0].link} target="_blank" rel="noopener">Ver ↗</a></div></article>{/each}</div>
{:else if aba==='escapadas'}
  <section class="intro"><p>PERTO DE {local.dupla.cidade.toUpperCase()}</p><h1>Uma pausa cabe<br/>neste fim de semana.</h1><span>Hotel na cidade, bate-e-volta ou dois dias por perto.</span></section><section class="escapechips"><button class:active={filtrosEscapada.formato==='Na cidade'} onclick={()=>filtrosEscapada.formato=filtrosEscapada.formato==='Na cidade'?'':'Na cidade'}>Na cidade</button><button class:active={filtrosEscapada.formato==='Perto de casa'} onclick={()=>filtrosEscapada.formato=filtrosEscapada.formato==='Perto de casa'?'':'Perto de casa'}>Perto de casa</button><button class:active={filtrosEscapada.formato==='Fim de semana'} onclick={()=>filtrosEscapada.formato=filtrosEscapada.formato==='Fim de semana'?'':'Fim de semana'}>Fim de semana</button><select aria-label="Estrelas mínimas" bind:value={filtrosEscapada.estrelas}><option value="">Estrelas</option><option value="4">4+ estrelas</option><option value="5">5 estrelas</option></select><select aria-label="Avaliação mínima" bind:value={filtrosEscapada.avaliacao}><option value="">Avaliação</option><option value="4.3">4,3+</option><option value="4.5">4,5+</option><option value="4.7">4,7+</option></select></section><section class="filter"><label><input type="checkbox" bind:checked={filtroQualidade}/> Aplicar o padrão de qualidade da dupla</label><button onclick={()=>ajustes=true}>Ajustar padrão</button></section>{#if !escapadas.length}<div class="empty"><b>Nenhuma opção passou pelos filtros.</b><p>Experimente retirar um filtro de qualidade ou ampliar o formato da escapada.</p></div>{/if}<div class="grid">{#each escapadas as e}<article class="card"><header><span>{e.icone}</span><div><h3>{e.nome}</h3><small>{e.destino} · {e.estrelas?`${e.estrelas} estrelas`:'sem estrelas informadas'}</small></div></header><p>★ {e.avaliacao??'—'} ({e.avaliacoes??0} avaliações) · {e.ranking.pontos}% de afinidade</p><b>{brl(e.preco_total)}<small> para dois</small></b><div class="actions"><button onclick={()=>avaliar(e,'nao_gostei')}>👎</button><button onclick={()=>avaliar(e,'gostei')}>👍</button><button onclick={()=>avaliar(e,'salvei')}>Salvar</button><a href={e.link} target="_blank" rel="noopener">Ver ↗</a></div></article>{/each}</div>
{:else if aba==='viagens'}
  <section class="intro"><p>RADAR DE OPORTUNIDADES</p><h1>Escolhas melhores,<br/>não só mais baratas.</h1><span>Cada card reúne o mesmo destino e mês. Datas alternativas ficam juntas.</span></section><div class="toolbar"><button onclick={()=>filtrosAbertos=true}>⚲ Filtros{filtrosAtivos?` · ${filtrosAtivos}`:''}</button><span>{[...new Set(ofertas.map((o)=>o.destino_texto))].length} destinos · {ofertas.length} oportunidades</span></div>{#if chipsAtivos.length}<section class="applied">{#each chipsAtivos as [label,remover]}<button onclick={remover}>{label} ×</button>{/each}<button class="clear" onclick={limparFiltros}>Limpar</button></section>{/if}{#if !ofertas.length}<div class="empty"><b>Nada com esses filtros.</b><p>Tente ampliar o orçamento, aceitar uma escala ou retirar um critério.</p><button onclick={limparFiltros}>Voltar à seleção recomendada</button></div>{/if}<div class="grid">{#each ofertas as o}{@const avaliacao=minhaAvaliacao(o)}<article class="card"><header><span>{flag(o.pais_iso2)}</span><div><h3>{o.destino_texto}</h3><small>São Paulo → {o.destino_texto} · {o.mes}</small></div></header><p class="why"><b>Por que apareceu</b>{o.explicacao}</p>{#if avaliacao}<div class:liked={avaliacao.acao==='gostei'} class:disliked={avaliacao.acao==='nao_gostei'} class="myfeedback"><b>{avaliacao.acao==='gostei'?'👍 Você gostou':'👎 Você não gostou'}</b>{#if avaliacao.motivos?.length}<span>{avaliacao.motivos.join(' · ')}</span>{/if}{#if avaliacao.nota}<small>“{avaliacao.nota}”</small>{/if}</div>{/if}<div class="price"><b>{brl(o.preco_brl*(o.por_pessoa?2:1))}<small> para dois</small></b>{#if o.quantidade>1}<span>+{o.quantidade-1} alternativa{o.quantidade>2?'s':''}</span>{/if}</div><div class="actions"><button class:selected={avaliacao?.acao==='nao_gostei'} aria-label={avaliacao?.acao==='nao_gostei'?'Não gostei — marcado':'Não gostei'} onclick={()=>avaliar(o,'nao_gostei')}>👎</button><button class:selected={avaliacao?.acao==='gostei'} aria-label={avaliacao?.acao==='gostei'?'Gostei — marcado':'Gostei'} onclick={()=>avaliar(o,'gostei')}>👍</button><button onclick={()=>avaliar(o,'salvei')}>Salvar</button><button onclick={()=>avaliar(o,'descartei')}>Ocultar</button></div></article>{/each}</div>
{:else}
  <section class="intro"><p>ESCOLHIDOS POR VOCÊS</p><h1>Planos para<br/>conversar depois.</h1></section><div class="grid">{#each [...ofertasPontuadas.filter((o)=>local.favoritos.includes(o.id)),...(dados.escapadas??[]).filter((e)=>local.escapadasFavoritas.includes(e.id))] as item}<article class="card"><h3>{item.destino_texto??item.nome}</h3><p>{item.destino??item.janela??'Escolha salva'}</p></article>{/each}</div>
{/if}</main>{/if}

{#if perfil}<div class="backdrop"></div><section class="modal"><p>SEU ESPAÇO</p><h2>Primeiro, conte<br/>sobre você.</h2><span>Cada pessoa configura o próprio aparelho. Depois vocês trocam um convite pelo WhatsApp.</span><label>Seu nome<input bind:value={nome} autocomplete="given-name" placeholder="Como podemos chamar você?"/></label><label>Cidade-base<select bind:value={cidade}><option>São Paulo</option></select></label><button class="primary wide" disabled={!nome.trim()} onclick={concluirPerfil}>Criar meu perfil →</button></section>{/if}
{#if local.migracao?.precisaEscolherPessoa}<div class="backdrop"></div><section class="modal"><p>MIGRAÇÃO SEGURA</p><h2>Quem está usando<br/>este aparelho?</h2><span>As escolhas anteriores foram preservadas. Agora cada aparelho precisa saber quem é você.</span>{#each pessoas as p}<button class="choice" onclick={()=>salvar(escolherPessoaMigrada(local,p.id))}>Eu sou {p.nome}</button>{/each}</section>{/if}
{#if preferencias}<button class="backdrop" aria-label="Fechar preferências" onclick={()=>preferencias=false}></button><section class="drawer"><button class="close" onclick={()=>preferencias=false}>×</button><p>SUAS PREFERÊNCIAS</p><h2>O que faz uma viagem valer a pena?</h2><div class="tastes">{#each TIPOS as [id,emoji,label]}<button class:on={(local.gosto[eu.id]??[]).includes(id)} onclick={()=>toggleGosto(id)}><span>{emoji}</span>{label}</button>{/each}</div><button class="primary wide" onclick={()=>{preferencias=false;if(!outra)compartilhar('convite')}}>{outra?'Salvar preferências':'Salvar e convidar'}</button></section>{/if}
{#if filtrosAbertos}<button class="backdrop" aria-label="Fechar filtros" onclick={()=>filtrosAbertos=false}></button><section class="drawer filtersheet"><header class="sheethead"><div><p>FILTROS DO RADAR</p><h2>Que viagem cabe agora?</h2></div><button class="close" onclick={()=>filtrosAbertos=false}>×</button></header>
  {#if local.buscasSalvas?.length}<div class="saved"><b>Buscas salvas</b>{#each local.buscasSalvas as busca}<button onclick={()=>aplicarBusca(busca)}>{busca.nome}</button>{/each}</div>{/if}
  <details open><summary><span>A viagem</span><small>Destino, período e orçamento</small></summary><div class="sectionbody">
    <fieldset><legend>Onde</legend><div class="segments"><button class:active={filtros.escopo==='perfil'} onclick={()=>filtros.escopo='perfil'}>Recomendada</button><button class:active={filtros.escopo==='domestico'} onclick={()=>filtros.escopo='domestico'}>Brasil</button><button class:active={filtros.escopo==='internacional'} onclick={()=>filtros.escopo='internacional'}>Exterior</button></div></fieldset>
    <div class="twocol"><label>Continente<select bind:value={filtros.continente}><option value="">Todos</option>{#each CONTINENTES as [id,label]}<option value={id}>{label}</option>{/each}</select></label><label>País<select bind:value={filtros.pais}><option value="">Todos</option>{#each paisesDisponiveis as [id,label]}<option value={id}>{label}</option>{/each}</select></label></div>
    <div class="twocol"><label>Mês<select bind:value={filtros.mes}><option value="">Datas flexíveis</option>{#each mesesDisponiveis as mes}<option value={mes}>{mes}</option>{/each}</select></label><label>Duração<select bind:value={filtros.duracao}><option value="perfil">Padrão recomendado</option>{#each DURACOES as [id,label]}<option value={id}>{label}</option>{/each}</select></label></div>
    <label>Orçamento total para duas pessoas <b>{brl(filtros.orcamentoCasal)}</b><input class="range" type="range" min="3000" max="20000" step="1000" bind:value={filtros.orcamentoCasal}/></label>
  </div></details>
  <details><summary><span>O voo</span><small>Conforto e praticidade</small></summary><div class="sectionbody"><label>Aeroporto de origem<select bind:value={filtros.origem}><option value="SAO">São Paulo (todos)</option></select></label><label>Escalas<select bind:value={filtros.escalas}><option value="">Qualquer quantidade</option><option value="0">Somente direto</option><option value="1">No máximo uma</option></select></label><label>Classe, quando informada<select bind:value={filtros.classe}><option value="">Qualquer classe</option><option value="economica">Econômica</option><option value="premium">Econômica premium</option><option value="executiva">Executiva</option></select></label><label class="checkrow"><input type="checkbox" bind:checked={filtros.bagagem}/> Bagagem incluída, quando a fonte informar</label><label class="checkrow"><input type="checkbox" bind:checked={filtros.semVisto}/> Sem necessidade de visto prévio</label></div></details>
  <details><summary><span>A experiência</span><small>Escolha uma ou mais</small></summary><div class="sectionbody tastechips">{#each TIPOS as [id,emoji,label]}<button class:active={filtros.tipos.includes(id)} onclick={()=>toggleTipo(id)}>{emoji} {label}</button>{/each}</div></details>
  <details><summary><span>Para vocês</span><small>Equilíbrio da dupla</small></summary><div class="sectionbody"><div class="segments vertical"><button class:active={filtros.afinidade===''} onclick={()=>{filtros.afinidade=''}}>Todas as compatíveis</button><button class:active={filtros.afinidade==='dupla'} onclick={()=>{filtros.afinidade='dupla'}}>Combina com os dois</button><button class:active={filtros.afinidade==='descoberta'} onclick={()=>{filtros.afinidade='descoberta'}}>Uma descoberta para o casal</button></div><small>A afinidade considera os gostos e as avaliações registradas separadamente em cada aparelho.</small></div></details>
  <details><summary><span>Sinais do Caçador</span><small>Qualidade da oportunidade</small></summary><div class="sectionbody"><label class="checkrow"><input type="checkbox" bind:checked={filtros.deal}/> Preço abaixo da média ou raro <small>Com base no histórico disponível para a rota.</small></label><label class="checkrow"><input type="checkbox" bind:checked={filtros.direto}/> Priorizar apenas voos diretos</label></div></details>
  <div class="savebox"><input bind:value={nomeBusca} placeholder="Nome desta busca"/><button onclick={salvarBusca}>Salvar busca</button></div>
  <footer class="sheetfoot"><button class="link" onclick={limparFiltros}>Limpar</button><button class="primary" onclick={aplicarFiltros}>Ver {[...new Set(ofertas.map((o)=>o.destino_texto))].length} destinos</button></footer>
</section>{/if}
{#if ajustes}<button class="backdrop" aria-label="Fechar ajustes" onclick={()=>ajustes=false}></button><section class="drawer"><button class="close" onclick={()=>ajustes=false}>×</button><p>QUALIDADE E DUPLA</p><h2>Seu padrão de viagem</h2><label>Hotel: mínimo de estrelas<select value={eu.qualidade?.hotelEstrelas??4} onchange={(e)=>atualizarQualidade('hotelEstrelas',+e.currentTarget.value)}><option value="3">3</option><option value="4">4</option><option value="5">5</option></select></label><label>Avaliação mínima<select value={eu.qualidade?.avaliacaoMinima??4.3} onchange={(e)=>atualizarQualidade('avaliacaoMinima',+e.currentTarget.value)}><option value="4">4,0</option><option value="4.3">4,3</option><option value="4.5">4,5</option><option value="4.7">4,7</option></select></label><label>Mínimo de avaliações<select value={eu.qualidade?.minimoAvaliacoes??100} onchange={(e)=>atualizarQualidade('minimoAvaliacoes',+e.currentTarget.value)}><option value="20">20</option><option value="100">100</option><option value="300">300</option></select></label><label><input type="checkbox" checked={eu.qualidade?.aceitarSemClassificacao??false} onchange={(e)=>atualizarQualidade('aceitarSemClassificacao',e.currentTarget.checked)}/> Aceitar hotel sem estrelas informadas</label><label>Classe da passagem<select value={eu.qualidade?.classeVoo??'economica'} onchange={(e)=>atualizarQualidade('classeVoo',e.currentTarget.value)}><option value="economica">Econômica</option><option value="premium">Econômica premium</option><option value="executiva">Executiva</option></select><small>Aplicada apenas quando a fonte informa a classe.</small></label><hr/>{#if outra}<button class="danger" onclick={confirmarDesvinculo}>Desvincular de {outra.nome}</button>{:else}<button class="primary wide" onclick={()=>compartilhar('convite')}>Convidar alguém</button>{/if}</section>{/if}
{#if feedback}<div class="backdrop"></div><section class="modal"><p>{feedback.acao==='nao_gostei'?'NÃO FAZ SEU ESTILO':'CONTE MAIS'}</p><h2>Por quê?</h2><span>Isso melhora as próximas sugestões. A observação livre fica somente neste aparelho.</span><div class="chips">{#each razoes(feedback.item.itemTipo) as r}<button class:on={motivos.includes(r)} onclick={()=>motivos=motivos.includes(r)?motivos.filter((x)=>x!==r):[...motivos,r]}>{r}</button>{/each}</div><label>Observação opcional<textarea bind:value={nota} placeholder="Ex.: muito simples para uma ocasião especial"></textarea></label><button class="primary wide" onclick={concluirFeedback}>Registrar escolha</button><button class="link" onclick={()=>feedback=null}>Cancelar</button></section>{/if}

<style>
:global(*){box-sizing:border-box}:global(body){margin:0;background:#07101c;color:#edf3fb;font-family:Inter,system-ui,sans-serif}:global(button),:global(input),:global(select),:global(textarea){font:inherit}.topbar,nav,main,.activity{width:min(1000px,calc(100% - 32px));margin:auto}.topbar{height:72px;display:flex;align-items:center;justify-content:space-between}.brand,.identity{border:0;background:none;color:inherit;display:flex;align-items:center;gap:10px;text-align:left}.brand>span{border:1px solid #f5a524;border-radius:10px;padding:7px;color:#f5a524}.brand small,.identity small{display:block;color:#7f91aa;font-size:10px}.identity{background:#101b2c;border:1px solid #203149;border-radius:12px;padding:7px 10px}.identity i{width:28px;height:28px;border-radius:50%;display:grid;place-items:center;background:#17405b;font-style:normal}.identity em{background:#f5a524;color:#111;border-radius:99px;padding:2px 6px;font-style:normal;font-size:10px}.notice{background:#2b2412;color:#ffe2a0;padding:10px 16px;display:flex;justify-content:center;gap:20px;font-size:12px}.notice button{background:none;border:0;color:inherit}.activity{margin-top:10px;border:1px solid #5a481d;background:#211e13;border-radius:14px;padding:13px;display:flex;align-items:center;gap:12px}.activity p{flex:1;margin:0;color:#baa979;font-size:11px}.activity button,.filter button{border:0;background:#f5a524;border-radius:8px;padding:8px 10px;font-size:10px}nav{display:flex;gap:22px;border-bottom:1px solid #1b2a40;overflow:auto}nav button{padding:13px 2px;border:0;border-bottom:2px solid transparent;background:none;color:#778ba5;white-space:nowrap}nav button.on{color:#f5a524;border-color:#f5a524}main{padding:30px 0 70px}.hero,.intro{padding:35px 0}.hero>p,.intro>p,.modal>p,.drawer>p,.role{font-size:10px;letter-spacing:.18em;color:#f5a524;font-weight:800}.hero h1,.intro h1,.modal h2,.drawer h2{font-family:Georgia,serif;font-size:clamp(40px,7vw,68px);line-height:.98;font-weight:500;margin:10px 0}.hero h1 em{color:#f5a524}.hero>span,.intro>span,.modal>span{color:#8b9cb2;line-height:1.6;font-size:13px}.heroactions{display:flex;gap:8px;margin-top:20px}.heroactions button,.primary{border:1px solid #344761;background:#142138;color:#fff;border-radius:10px;padding:11px 14px}.primary{background:#f5a524!important;color:#111!important;border:0!important;font-weight:700}.radarline,.toolbar{display:flex;justify-content:space-between;gap:10px;border:1px solid #273953;background:#0d1726;border-radius:12px;padding:11px 13px;margin-bottom:14px;font-size:10px;color:#8294ab}.radarline b{color:#edf3fb}.toolbar button{border:0;background:none;color:#f5a524}.grid{display:grid;grid-template-columns:1fr 1fr;gap:12px}.card{border:1px solid #22334d;background:#101b2c;border-radius:17px;padding:16px}.card.featured{border-color:#3b4560}.card header{display:flex;align-items:center;gap:10px}.card header>span{font-size:28px}.card h3{margin:0;font-size:16px}.card small,.card p{color:#8294ab;font-size:10px}.role{margin:0 0 10px!important}.signals{display:flex;flex-wrap:wrap;gap:5px;margin:11px 0}.signals span{font-size:9px;border:1px solid #35455f;border-radius:99px;padding:4px 7px}.why{min-height:39px;line-height:1.45}.why b{display:block;color:#dce5ef;text-transform:uppercase;font-size:8px;letter-spacing:.1em}.price{display:flex;justify-content:space-between;align-items:end}.price span{font-size:9px;color:#f5a524}.actions{display:flex;gap:6px;margin-top:14px}.actions button,.actions a{border:0;background:#1d2d45;color:#d9e2ed;text-decoration:none;padding:8px;border-radius:8px;font-size:10px}.actions a{margin-left:auto;background:#f5a524;color:#111}.filter{border:1px solid #263852;background:#0d1726;border-radius:13px;padding:10px 13px;display:flex;justify-content:space-between;align-items:center;margin-bottom:14px;font-size:11px}.empty{text-align:center;color:#8294ab;padding:60px 20px}.empty button{border:0;border-radius:8px;padding:8px;margin-top:8px}.backdrop{position:fixed;inset:0;background:#040912dd;border:0;padding:0;z-index:20}.modal,.drawer{position:fixed;z-index:21;background:#101b2c;border:1px solid #293a55;padding:28px;box-shadow:0 30px 90px #000b}.modal{inset:50% auto auto 50%;transform:translate(-50%,-50%);width:min(440px,calc(100% - 28px));border-radius:22px}.modal h2,.drawer h2{font-size:32px}.modal label,.drawer label{display:block;color:#9aabc0;font-size:11px;margin-top:13px}.modal input,.modal select,.modal textarea,.drawer select{width:100%;margin-top:5px;background:#091421;border:1px solid #30425d;color:#fff;border-radius:10px;padding:11px}.modal textarea{min-height:70px}.wide{width:100%;margin-top:18px}.choice{width:100%;margin-top:8px;border:1px solid #344761;background:#142138;color:#fff;border-radius:10px;padding:12px}.drawer{right:0;top:0;bottom:0;width:min(500px,100%);overflow:auto}.close{float:right;border:0;background:none;color:#fff;font-size:24px}.tastes{display:grid;grid-template-columns:1fr 1fr;gap:7px}.tastes button,.chips button{border:1px solid #293a55;background:#121f33;color:#dce5ef;border-radius:10px;padding:10px;text-align:left}.tastes button.on,.chips button.on{border-color:#f5a524;background:#292716}.tastes span{margin-right:8px}.chips{display:flex;flex-wrap:wrap;gap:6px}.chips button{padding:7px 9px;font-size:10px}.drawer hr{border:0;border-top:1px solid #293a55;margin:22px 0}.danger{width:100%;border:1px solid #773f46;background:#321a20;color:#ffb8c0;border-radius:10px;padding:11px}.link{width:100%;border:0;background:none;color:#8fa0b6;padding:10px}.drawer label small{display:block;margin-top:4px}.drawer input[type=checkbox],.checks input{width:auto;margin-right:6px}.checks{display:grid;grid-template-columns:1fr 1fr}.checks label{background:#0b1625;padding:8px;border-radius:8px}.filtersheet label{margin-top:9px}
.myfeedback{display:grid;gap:4px;margin:12px 0;padding:10px;border:1px solid #32445e;border-radius:10px;background:#0b1625}.myfeedback.liked{border-color:#287c63;background:#0c241f}.myfeedback.disliked{border-color:#8a4650;background:#2a171c}.myfeedback b{font-size:11px}.myfeedback span,.myfeedback small{color:#aab9cb;font-size:9px}.actions button.selected{background:#f5a524;color:#111;box-shadow:0 0 0 2px #f5a52455}
.quickfilters,.escapechips,.applied{display:flex;gap:7px;overflow-x:auto;padding:2px 0 12px;scrollbar-width:none}.quickfilters button,.escapechips button,.applied button,.saved button,.tastechips button,.segments button{white-space:nowrap;border:1px solid #2b3d58;background:#101b2c;color:#c8d3e1;border-radius:99px;padding:8px 11px;font-size:10px}.quickfilters button.active,.escapechips button.active,.tastechips button.active,.segments button.active{border-color:#f5a524;background:#2d2918;color:#ffe3a0}.applied{align-items:center;color:#7f91aa;font-size:10px}.applied button{padding:6px 9px;background:#16243a}.applied .clear{border:0;background:none;color:#f5a524}.escapechips select{border:1px solid #2b3d58;background:#101b2c;color:#c8d3e1;border-radius:99px;padding:7px 10px;font-size:10px}.sheethead{position:sticky;top:-28px;background:#101b2cf5;z-index:2;padding-top:28px;display:flex;justify-content:space-between}.sheethead p{font-size:10px;letter-spacing:.18em;color:#f5a524;font-weight:800}.sheethead h2{margin-top:6px}.filtersheet details{border-top:1px solid #293a55}.filtersheet summary{list-style:none;padding:15px 0;cursor:pointer;display:flex;justify-content:space-between}.filtersheet summary span{font-weight:700}.filtersheet summary small{color:#7f91aa}.sectionbody{padding:0 0 18px}.twocol{display:grid;grid-template-columns:1fr 1fr;gap:8px}.segments{display:flex;gap:6px}.segments button{flex:1}.segments.vertical{flex-direction:column}.segments.vertical button{text-align:left}.tastechips{display:flex;flex-wrap:wrap;gap:7px}.filtersheet fieldset{border:0;padding:0;margin:0}.filtersheet legend{font-size:11px;color:#9aabc0;margin-bottom:6px}.filtersheet .range{width:100%;accent-color:#f5a524}.checkrow{border:1px solid #263852;border-radius:10px;padding:10px;background:#0b1625}.saved{display:flex;gap:6px;align-items:center;overflow:auto;margin-bottom:12px}.saved b{font-size:10px;color:#8fa0b6;white-space:nowrap}.savebox{display:flex;gap:6px;margin:15px 0 80px}.savebox input{min-width:0;flex:1;background:#091421;border:1px solid #30425d;color:#fff;border-radius:10px;padding:10px}.savebox button{border:0;border-radius:10px;padding:10px;background:#243650;color:#fff}.sheetfoot{position:fixed;right:0;bottom:0;width:min(500px,100%);display:grid;grid-template-columns:90px 1fr;gap:8px;background:#101b2cf5;border-top:1px solid #293a55;padding:12px 28px}.sheetfoot .primary{margin:0}
@media(max-width:700px){.topbar{height:62px}.brand small,.identity span{display:none}.activity{align-items:flex-start;flex-wrap:wrap}.activity p{flex-basis:60%}.grid{grid-template-columns:1fr}.hero,.intro{padding:25px 0}.hero h1,.intro h1{font-size:44px}.heroactions{display:grid;grid-template-columns:1fr 1fr}.heroactions .primary{grid-column:1/-1}.filter,.radarline{align-items:flex-start;flex-direction:column}.tastes{grid-template-columns:1fr 1fr}.drawer{padding:22px}.twocol{grid-template-columns:1fr}.sheetfoot{padding:12px 22px}}
</style>
